toad_implementation.code_blueprint:
canvas {
  size: 800px 800px;
  fill: #030712;
  font-family: "Space Grotesk, sans-serif";
}

>void = #030712;
>cyan = #38BDF8;
>rose = #F43F5E;
>gold = #FBBF24;

rect #layerRot0 {
  at: center of canvas offset 0px -40px;
  size: 320px 320px;
  fill: none;
  stroke: >cyan;
  stroke-width: 1.5px;
}

rect #layerRot15 {
  at: center of canvas offset 0px -40px;
  size: 320px 320px;
  fill: none;
  stroke: >rose;
  stroke-width: 1.5px;
  rotation: 15deg;
}

rect #layerRot30 {
  at: center of canvas offset 0px -40px;
  size: 320px 320px;
  fill: none;
  stroke: >gold;
  stroke-width: 1.5px;
  rotation: 30deg;
}

rect #layerRot45 {
  at: center of canvas offset 0px -40px;
  size: 320px 320px;
  fill: none;
  stroke: >cyan;
  stroke-width: 1.5px;
  rotation: 45deg;
}

text #pieceTitle {
  at: below #layerRot0 offset 80px;
  content: "M O I R É   I T E R A T I O N   # 4 2";
  font-size: 20px;
  font-weight: 600;
  color: #F8FAFC;
}

text #mathSignature {
  at: below #pieceTitle offset 10px;
  content: "GEN_SEED: 0x8F3A29 • ALGORITHM: N-FOLD HARMONIC ROTATION";
  font-size: 11px;
  color: >cyan;
}
